{
 "research_concepts": [
  "lineup coverage",
  "structural roles",
  "organizer role",
  "shaper role",
  "terminal role",
  "player talent",
  "role separability",
  "talent control",
  "lineup composition"
 ],
 "methodological_questions": [
  "definition and measurement of structural roles",
  "quantifying lineup composition by roles",
  "assessing within-team variability of role coverage",
  "methods to separate role impact from talent/counts",
  "modeling the influence of talent/roles on game outcomes",
  "controlling for confounding factors (e.g., team quality, player positions)"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-CHT-009",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph. Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap)."
  },
  {
   "id": "FAM:SF-PAP-034",
   "status_as_recorded": "no result recorded",
   "finding": "Structural load is not an artifact of position or low initiation volume (Gobert vs other C/F-C; init<400 vs >=400). No result recorded."
  },
  {
   "id": "FAM:SF-CHT-029",
   "status_as_recorded": "artifact",
   "finding": "Play-type actions have decaying cross-possession memory (lag-1 effect >= lag-2; not just score margin or team quality). FAIL decay-sanity: DRIVE lifts +0.015,+0.020,+0.018,+0.021,+0.020 (flat). Within-team: DRIVE lag-1 +0.015 to -0.002. Cohen d ~0.01-0.03; p~0 from n>150k. Callable play-type horizons = 0."
  },
  {
   "id": "FAM:SF-PAP-024",
   "status_as_recorded": "rejected",
   "finding": "Teams whose structural influence is concentrated are more defensively vulnerable. C1a rho=+0.079 p=0.0882 CI[-0.114,+0.234]; C1b rho=+0.095 p=0.0738; robust 0.2/0.3 also fail."
  },
  {
   "id": "FAM:SF-APPS-036",
   "status_as_recorded": "supported",
   "finding": "The team-level BEST vs AVOID gap holds when H2 possessions are filtered to initiating player. Mean gap (n>=10 each tier) +0.427 PPP. Mean BEST 1.347 (38 players) vs AVOID 0.920 (94 players). Stars mean gap +0.542 (n=15) vs role +0.428 (n=16). Only 3 players clear n>=30 both tiers (all BOS: White +0.864, Brown +0. [cut; read_family for the full text]"
  },
  {
   "id": "FAM:SF-APPS-015",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Teams and players differ in how often H2 trigger possessions land on the engine's BEST vs AVOID counter. Team AVOID% ranges 50.6% (ORL) to 6.8% (SAC); team BEST% 0.0%-15.8%."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-CHT-009",
   "what_failed": "Assessing superstar suppression by lineup without placebo or matching.",
   "why": "E_unclear (mechanism unclear from the records); later sequence work treated similar star-chain gaps as artifacts."
  },
  {
   "id": "FAM:SF-PAP-034",
   "what_failed": "Attempt to sanity check structural load against position or initiation volume.",
   "why": "E_unclear (mechanism unclear from the records); no result CSV/log of the printed tables was found, study abandoned."
  },
  {
   "id": "FAM:SF-CHT-029",
   "what_failed": "Detecting decaying cross-possession memory of play-type actions.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); flat non-decaying lifts collapse under within-team baseline; team-quality confound."
  },
  {
   "id": "FAM:SF-PAP-024",
   "what_failed": "Testing if structural influence concentration predicts defensive vulnerability.",
   "why": "B_powered_null (adequately powered null result); not underpowered (30 franchises) but CI spans 0."
  }
 ],
 "evidence_establishes": [
  "Player-level talent (BEST vs AVOID play types) has a measurable impact on Points Per Possession (PPP) even when filtered by initiating player (FAM:SF-APPS-036).",
  "There is variability in how often teams and players utilize 'BEST' vs 'AVOID' play types (FAM:SF-APPS-015).",
  "Apparent effects can be artifacts of confounding factors like team quality, necessitating within-team baselines (FAM:SF-CHT-029).",
  "Previous attempts to link 'structural influence' concentration to defensive vulnerability yielded null results, with confidence intervals spanning zero (FAM:SF-PAP-024).",
  "Superstar performance can vary by lineup composition and forced play type, but these observations require careful control for confounding (FAM:SF-CHT-009)."
 ],
 "evidence_does_not_establish": [
  "How to define and measure 'organizer', 'shaper', and 'terminal' structural roles.",
  "Whether lineup coverage of these specific structural roles varies within teams.",
  "Methods to rigorously separate the impact of structural roles from player talent or simple player counts.",
  "Whether 'talent control' (in the context of structural roles) behaves in a predictable or measurable way.",
  "Whether 'structural load' (a related concept) is independent of position or initiation volume, as the relevant study was abandoned (FAM:SF-PAP-034).",
  "A clear framework for modeling the interaction between structural roles and player talent."
 ],
 "own_inferences": [
  "The concept of 'structural roles' (organizer, shaper, terminal) is not explicitly defined or measured in the retrieved historical evidence, suggesting this is a novel definition within the project.",
  "The current data, with play-by-play, substitution, box-score, and derived play-type records, is likely sufficient to *define* and *measure* these roles, given previous work on 'structural load' and 'player routing'.",
  "Separating role impact from talent will require robust statistical controls, potentially including player-fixed effects, lineup-fixed effects, or other methods to account for player quality and usage.",
  "The phrase 'talent control behaves' likely refers to how individual player talent (e.g., usage, efficiency) is expressed or constrained within different role configurations, or how its impact is modulated."
 ],
 "uncertainties": [
  "The precise definitions of 'organizer', 'shaper', and 'terminal' roles are not provided in the research question or historical evidence. Their operationalization is a key uncertainty.",
  "How 'talent' and 'counts' will be defined and measured to assess separability from roles.",
  "The specific meaning of 'talent control behaves' is ambiguous and requires clarification.",
  "The specific statistical methods intended to demonstrate 'separability' are not detailed."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence highlighted a strong need for clear definitions of structural roles, robust controls for confounding (especially team quality and within-team variation), and awareness of sample size limitations at the player/lineup level. The abandonment of FAM:SF-PAP-034 on 'structural load' and the null result of FAM:SF-PAP-024 on 'structural concentration' suggest that operationalizing and demonstrating the impact of structural concepts is challenging. This pushes the decision towards 'proceed_with_changes' to ensure these foundational aspects are addressed in the design, particularly the definitional clarity and the robust separation methodology."
 },
 "testability": {
  "p_testable": 0.6,
  "blocking_constraints": [
   {
    "code": "CONFOUNDING",
    "text": "Separating role effects from player talent and team quality is a significant challenge, as demonstrated by FAM:SF-CHT-029 where apparent effects collapsed under within-team baselines due to team-quality confound."
   },
   {
    "code": "MEASURE_RELIABILITY",
    "text": "The definitions and reliable measurement of 'organizer', 'shaper', and 'terminal' roles are not established and are critical for testability. Without clear, validated definitions, any findings would be difficult to interpret."
   },
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "While total possessions are high, analyzing specific lineup coverages and player-level 'talent control' within those coverages will likely lead to sparse data cells, as seen in FAM:SF-APPS-036 where only 3 players met a modest N>=30 threshold for both BEST/AVOID tiers."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": [
   "FAM:SF-PAP-034",
   "FAM:SF-PAP-024"
  ],
  "summary": "No prior work directly addressed the specific question of lineup coverage of 'organizer, shaper, terminal' roles, their separability from talent/counts, and how 'talent control behaves'. Previous studies touched on related concepts like 'structural load' (FAM:SF-PAP-034, abandoned) and 'structural influence' (FAM:SF-PAP-024, null result), suggesting challenges in defining and demonstrating such structural impacts. Other studies focused on player-level talent and routing (FAM:SF-APPS-036, FAM:SF-CHT-009) or general methodological issues like confounding (FAM:SF-CHT-029)."
 },
 "risks": [
  {
   "code": "MEASURE_RELIABILITY",
   "text": "The definitions of 'organizer', 'shaper', and 'terminal' roles must be rigorously established and validated. Ambiguous definitions will undermine the entire study."
  },
  {
   "code": "CONFOUNDING",
   "text": "Player talent, overall team quality, coaching schemes, and opponent strength are major confounders. Robust controls (e.g., player fixed effects, matched samples, within-team analysis) are essential to separate role impact from these factors, as highlighted by FAM:SF-CHT-029."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "While total possessions are ample, the number of possessions for specific lineup combinations with defined role coverages, especially for individual players within those roles, may be insufficient to detect effects with useful power. This was a limitation in FAM:SF-APPS-036 and FAM:SF-PAP-024."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "Certain combinations of role coverage might be rare, leading to sparse data for analysis of their effects or 'talent control' behaviors."
  },
  {
   "code": "MECHANICAL_FLOOR",
   "text": "If role definitions are based on initiation or usage thresholds, there may be mechanical floors/ceilings that limit observed variation or create artifacts."
  }
 ],
 "predicted_outcome": {
  "supported": 0.2,
  "rejected": 0.3,
  "untestable": 0.2,
  "artifact": 0.1,
  "uncertain": 0.2
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The estimand is threefold: (1) The variance of lineup role coverage (>=1 organizer, shaper, terminal) within each team. (2) The unique contribution of role coverage to lineup offensive efficiency (PPP) after controlling for player talent and counts. (3) The interaction effect of player talent (e.g., usage-adjusted efficiency) with different role coverages on lineup offensive efficiency.",
  "unit": "Possession. Lineup-level aggregated measures will be derived from possessions.",
  "sample": "All available NBA 2022-23 to 2025-26 regular season and playoff possessions (420,993 possessions; 90 team-seasons) where a complete lineup and player roles can be identified. Minimum possession thresholds per lineup (e.g., 50 possessions) will be applied for statistical stability.",
  "power": "Power will be assessed based on the effective sample size of unique lineup-role configurations. A minimum detectable effect size for PPP (e.g., 0.05 PPP) will be targeted, and power calculations will inform the minimum required observations per cell/lineup.",
  "controls": "To address separability and confounding, the analysis will include: (1) Player-fixed effects to control for individual talent. (2) Lineup-fixed effects or matched-lineup designs (e.g., same 4 players, different 5th) to control for overall lineup quality. (3) Opponent strength and game context (score margin, quarter, home/away) as covariates. (4) Player counts (e.g., #guards, #forwards) in the lineup to distinguish role effects from simple positional composition. Within-team analysis will be prioritized to control for team-level confounding, following lessons from FAM:SF-CHT-029.",
  "falsification": "The research question includes three parts. Falsification for (1) would be the demonstration of no significant within-team variance in role coverage (e.g., coefficient of variation near zero). Falsification for (2) would be a null or negligible effect of role coverage on PPP after controlling for talent/counts. Falsification for (3) would be a null interaction effect between talent and role coverage, or talent control behaving in an unexpected or inconsistent manner across role structures. Clear operational definitions of 'organizer', 'shaper', and 'terminal' roles (e.g., based on play-type initiation, assist types, shot creation) must be established and documented before analysis.",
  "multiplicity": "Given the multi-part nature of the question, a Bonferroni correction or similar adjustment for multiple comparisons will be applied if multiple hypothesis tests are conducted on related outcomes or role definitions. Each part of the question will be treated as a distinct analysis objective.",
  "decision_rule": "For descriptive parts, clear metrics for 'variance' will be defined. For hypothesis tests, a p-value threshold of 0.05 will be used for statistical significance. Practical significance will also be considered (e.g., effect size on PPP). Support for separability requires a statistically significant and practically meaningful effect of role coverage independent of talent/counts. Support for 'talent control behaves' requires a statistically significant interaction effect where talent's impact is modulated by role coverage as hypothesized.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25, and 2025-26 regular season and playoff data, as of 2026-07-13. Derived play-type possession records from the graph database will be used."
 }

